#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

#define pii pair<int, int>
#define mp make_pair

const int mod1 = 998244353;
const int mod2 = 1000000007;
const int Base = 1000000;

int n, tot, sum[15], ans;
vector<int> vec[15];

void dfs1(int k, int num) {
    if (k == 7) return;
    tot++;
    int back = ((tot - num) % mod1 + mod1) % mod1;
    vec[k].push_back(back);
    sum[k] = (sum[k] + back) % mod2;
    for (int i = 0; i <= 9; ++i) {
        dfs1(k + 1, num * 10 + i);
    }
}

void dfs2(int x) {
    if (x > n) return;
    if (x * Base + Base - 1 <= n && x * Base * 10 > n) {
        int now = tot;
        for (int i = 0, mul = 1; i <= 6; ++i, mul *= 10) {
            int sz = (int)vec[i].size();
            int dif = ((now - x * mul) % mod1 + mod1) % mod1;
            int pos = (int)(lower_bound(vec[i].begin(), vec[i].end(), (int)(mod1 - dif)) - vec[i].begin());
            ans = (ans + dif * sz + sum[i]) % mod2;
            ans = (ans - (long long)mod1 * (sz - pos) % mod2 + mod2) % mod2;
            tot += sz;
        }
        return;
    }
    tot++;
    ans = (ans + ((tot - x) % mod1 + mod1) % mod1) % mod2;
    for (int i = 0; i <= 9; ++i) {
        dfs2(x * 10 + i);
    }
}

int main() {
    cin >> n;
    dfs1(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(vec[i].begin(), vec[i].end());
    }
    tot = 0;
    for (int i = 1; i <= 9; ++i) {
        dfs2(i);
    }
    cout << ans << endl;
    return 0;
}
